/**
 * JSS 3 Lesson Note Templates
 * English Language, Mathematics, Basic Science — All 3 Terms × 12 Weeks
 * Civic Education — All 3 Terms × 12 Weeks
 * Original content based on Nigerian NERDC curriculum.
 */
import type { LNTemplate } from "./seed-jss-lesson-notes-1";

function lnt(
  className: string, subjectName: string, level: string,
  term: string, weekNumber: number, topic: string,
  objectives: string, content: string, evalQ: string, assign: string, refs: string
): LNTemplate {
  return {
    title: `${className} ${subjectName} – ${topic}`, level, className, subjectName,
    term, weekNumber, topic, duration: "40 minutes", objectives,
    entryBehaviour: "Students have foundational knowledge from the previous class.",
    instructionalMaterials: "Textbook, whiteboard, markers, relevant specimens/charts.",
    content, teacherActivities: "Step 1 (5 min): Review previous lesson. Step 2 (10 min): Introduce new concept. Step 3 (15 min): Detailed explanation with examples. Step 4 (8 min): Class exercises. Step 5 (2 min): Summary and evaluation.",
    studentActivities: "• Listen and take notes.\n• Participate in discussion.\n• Complete exercises.\n• Ask and answer questions.",
    evaluationQuestions: evalQ, assignments: assign, references: refs,
  };
}

